<?php

namespace Ediligence\EdiligenceBundle\Repository;

/**
 * AffecterRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class TcourrierRepository extends \Doctrine\ORM\EntityRepository {

    public function recover_enreg($todo) {
        $qb1 = $this->createQueryBuilder('m')
                ->select('count(m.numenregistrement) AS max_enreg')
                ->where('m.typecourrier =:todo')
                ->setParameter('todo', $todo)
                ->setMaxResults(1)
                ->getQuery()->getOneOrNullResult();
       
      if($qb1['max_enreg']==null){$qb1['max_enreg']=0;}
        return $qb1['max_enreg'];
    }

    public function max_courrier() {
        $qb = $this->createQueryBuilder('c')
                ->select('c.id')
                ->orderBy('c.id','DESC')
                ->setMaxResults(1);
        $res=$qb->getQuery()->getOneOrNullResult();
        if($res==null){
            return 0;
        }else{
            return $res['id'];
        }
    }

     public function allfind($param, $service){
        $qb = $this->createQueryBuilder('c')
                ->where('c.typecourrier = :param')
                ->setParameter('param', $param)
                ->andWhere('c.servicesaisi =:servicesaisi')
                ->setParameter('servicesaisi', $service)
                ->orderBy('c.id', 'DESC'); 
        return $qb->getQuery()->getResult();  
    }
    
     public function find_depart_recu($service){
        $qb = $this->createQueryBuilder('c')
                   ->where('c.departdest Is not null')
                   ->andWhere("c.departdest Like :service ")
                  ->setParameter("service", '%'.$service.'%');  
        return $qb->getQuery()->getResult();  
    } 
    
}
